// Git: Complete Guide. About 60 minutes, beginner to advanced. Terminal output in this file was captured from
// real Git sessions (git 2.54) on 8 Nov 2026; commit IDs will differ on your machine.
module.exports = {
  id: 'git', title: 'Git: Complete Guide', sub: 'From git init to rebase, bisect, worktrees, hooks and Git 3.0', cat: 'Version control',
  accent: '#f05133', icon: 'git', target: 60, keyword: 'GIT', tags: '#git #github #devops',
  scenes: [
    { type: 'hook', title: 'Git: Complete Guide', kicker: 'Version control · 60 minutes', q: 'What really happens inside that .git folder?',
      n: 'Every DevOps pipeline starts with one command: git push. But most people use Git like a magic box, and panic the moment something goes wrong. In the next hour, we open the box. We start from an empty folder, watch every file change state, build branches and merges step by step, and finish with the advanced tools that senior engineers use to recover from almost anything. Type along with me.' },
    { type: 'roadmap', n: 'Here is the plan, in eleven sections. Foundations and setup. Your first repository. Undoing changes safely. Branching and merging. Remotes and collaboration. Rewriting history. Inspecting and debugging. Configuration and tooling. Large repositories. Security. And finally, workflows, and what changes in Git three.' },

    // ---------------------------------------------------------------- Foundations
    { sec: 'Foundations', title: 'What version control solves', icon: 'clock',
      items: [['file', 'final_v2_REALLY_final.docx', 'Copies by hand do not scale'], ['users', 'Many people, one codebase', 'Who changed what, and why'], ['refresh', 'Go back in time', 'Any version, any file, any day']],
      tip: 'Git records snapshots of your project, with who, when and why for each one.',
      n: 'Step one: what problem are we solving? Without version control, people copy folders, with names like final version two, really final. That breaks down as soon as two people work together. Version control records every change, who made it, when, and why, so you can always answer what changed, and go back to any earlier version.' },
    { sec: 'Foundations', title: 'Centralised vs distributed', cols: ['Centralised (SVN)', 'Distributed (Git)'],
      rows: [['History lives', 'On one server', 'In every clone'], ['Offline work', 'Very limited', 'Commit, branch, log, all offline'], ['Branching', 'Heavy, slow', 'Cheap: a branch is a 41-byte file'], ['If the server dies', 'History can be lost', 'Any clone can restore it']],
      tip: 'GitHub, GitLab and Azure Repos are hosts for Git. Git itself runs on your machine.',
      n: 'Step two: centralised versus distributed. Older tools, like Subversion, keep the history on one server. Git is distributed: every clone holds the complete history. That means you can commit, branch, and read the log fully offline, and branching is almost free. Remember this: GitHub and GitLab are places that host Git. Git itself runs on your laptop.' },
    { sec: 'Foundations', title: 'Snapshots, not differences', nodes: [['file', 'Version 1', 'app.py, README.md'], ['file', 'Version 2', 'app.py changed'], ['file', 'Version 3', 'README.md changed']], edges: ['commit', 'commit'],
      tip: 'Unchanged files are not copied again. Git just points to the version it already stored.',
      n: 'Step three: how Git thinks. Many tools store a list of differences. Git stores snapshots. Each commit is a picture of the whole project at that moment. That sounds wasteful, but it is not: if a file did not change, Git simply points to the copy it already has. This snapshot model is why switching branches is so fast.' },
    { sec: 'Foundations', title: 'The three areas', nodes: [['folder', 'Working tree', 'files you edit'], ['inbox', 'Staging area', 'the index'], ['database', 'Repository', '.git: commits']], edges: ['git add', 'git commit'],
      items: [['file', 'git restore', 'Discard working-tree edits'], ['upload', 'git restore --staged', 'Unstage, keep the edit'], ['download', 'git switch / checkout', 'Load a commit into the tree']],
      tip: 'Almost every Git command moves changes between these three areas.',
      n: 'Step four: the most important picture in Git. There are three areas. The working tree, which holds the files you edit. The staging area, also called the index, where you prepare the next commit. And the repository, inside the dot git folder, where commits are stored for good. git add moves changes into staging, and git commit records them. git restore goes the other way.' },
    { sec: 'Foundations', title: 'The life cycle of a file', cols: ['State', 'Meaning', 'Moves on with'],
      rows: [['Untracked', 'Git has never seen it', 'git add'], ['Staged', 'In the next commit', 'git commit'], ['Committed', 'Saved in history', 'edit the file'], ['Modified', 'Changed since the last commit', 'git add'], ['Ignored', 'Listed in .gitignore', 'never tracked']],
      n: 'Step five: every file is in one of five states. Untracked: Git has never seen it. Staged: it will be in the next commit. Committed: it is saved in history. Modified: you changed it after the last commit. And ignored: it matches a rule in dot git ignore, so Git never tracks it. Watch for these colours; you will see them on every folder in this video.' },
    { sec: 'Setup', title: 'Install and check the version', cmd: ['$ git --version', 'git version 2.56.0', '# macOS:   brew install git', '# Ubuntu:  sudo apt install git', '# Windows: winget install Git.Git'],
      tip: 'Git 2.56 is the latest stable release (November 2026).',
      n: 'Step six: install Git, and check the version. On a Mac, use Homebrew. On Ubuntu, apt. On Windows, winget. Then run git dash dash version. The latest stable release, as of November twenty twenty six, is two point five six. Most of what we cover works on any version from the last few years.' },
    { sec: 'Setup', title: 'Configure who you are', cmd: ['$ git config --global user.name "Kona Srinivas"', '$ git config --global user.email "kona@example.com"', '$ git config --global init.defaultBranch main', '$ git config --global pull.rebase true', '$ git config --global core.editor "code --wait"', '$ git config --list --show-origin | head -n 3'],
      tip: 'Every commit is stamped with this name and email. Use your work email on work repos.',
      n: 'Step seven: tell Git who you are. Set your name and email, because every commit is stamped with them. Make main the default branch name for new repositories. Set pull to rebase, which keeps history tidy, and choose your editor. dash dash list, with show origin, tells you which file each setting came from.' },
    { sec: 'Setup', title: 'The three config levels', cols: ['Level', 'File', 'Applies to'],
      rows: [['--system', '/etc/gitconfig', 'Every user on the machine'], ['--global', '~/.gitconfig', 'You, in every repository'], ['--local', '.git/config', 'This repository only'], ['includeIf', 'gitdir:~/work/', 'A different email for work folders']],
      tip: 'The most specific level wins: local beats global, global beats system.',
      n: 'Step eight: config has three levels. System applies to every user on the machine. Global applies to you, in every repository. Local applies to one repository, and wins over the others. A great trick is include if: point it at your work folder, and Git uses your work email automatically, only for those repositories.' },
    { sec: 'Setup', title: 'Get help without leaving the terminal', cmd: ['$ git help -g', '$ git status -h', 'usage: git status [<options>] [--] [<pathspec>...]', '$ git help rebase    # full manual page', '$ git help -a | head -n 3'],
      tip: 'Short help with -h, the full manual with git help <command>.',
      n: 'Step nine: help is always one command away. Dash h after any command prints a short summary of its options. git help, followed by a command name, opens the full manual page, with examples. git help dash g lists the concept guides, such as the glossary and the everyday Git guide. You rarely need to search the web for basic options.' },

    // ---------------------------------------------------------------- First repository
    { type: 'tree', sec: 'Your first repository', title: 'git init: a folder becomes a repo', root: 'shop-api/',
      files: [['.git/', '', 'the whole repository'], ['.git/HEAD', '', 'points to the current branch'], ['.git/config', '', 'local settings'], ['.git/objects/', '', 'all content, compressed'], ['.git/refs/', '', 'branches and tags'], ['.git/hooks/', '', 'sample scripts']],
      cmd: ['$ mkdir shop-api && cd shop-api', '$ git init', 'Initialized empty Git repository in ~/shop-api/.git/', '$ ls .git', 'HEAD  config  description  hooks  info  objects  refs'],
      tip: 'Delete .git and the folder is a plain folder again. Everything Git knows lives there.',
      n: 'Step ten: git init. We make a folder called shop api, and run git init. Git creates one hidden folder: dot git. That is the entire repository. HEAD points to the current branch. config holds local settings. objects stores every version of every file, compressed. refs holds branches and tags, and hooks holds sample scripts. Delete dot git, and your folder is just a folder again.' },
    { sec: 'Your first repository', title: 'Three ways to start', cols: ['Command', 'When'],
      rows: [['git init', 'A new project in an existing folder'], ['git clone <url>', 'A project that already exists on a server'], ['git init --bare repo.git', 'A server copy with no working tree'], ['switch --orphan', 'A new branch with no history, like a docs site']],
      tip: 'A bare repository has no working files. Servers and shared remotes use bare repos.',
      n: 'Step eleven: three ways to start. git init turns an existing folder into a repository. git clone copies one that already exists on a server. git init dash dash bare creates a server style repository with no working files, which is what GitHub keeps behind the scenes. And switch dash dash orphan starts a branch with no history at all, which is handy for a documentation site.' },
    { type: 'tree', sec: 'Your first repository', title: 'New files are untracked', root: 'shop-api/',
      files: [['.git/', 'I', 'not shown by status'], ['README.md', 'U', 'new'], ['app.py', 'U', 'new']],
      cmd: ['$ echo "# Shop API" > README.md', "$ printf 'print(\"hello\")\\n' > app.py", '$ git status', 'On branch main', 'No commits yet', 'Untracked files:', '	README.md', '	app.py'],
      tip: 'Untracked means Git sees the file but is not recording it yet.',
      n: 'Step twelve: create two files, a readme and app dot py, and run git status. Both are untracked. Git can see them, but it is not recording their history. Notice the message: no commits yet. git status is the command you will run most often, so make it a habit after every step.' },
    { type: 'tree', sec: 'Your first repository', title: 'git add: stage what you want', root: 'shop-api/',
      files: [['README.md', 'A', 'in the next commit'], ['app.py', 'U', 'still untracked']],
      cmd: ['$ git add README.md', '$ git status -s', 'A  README.md', '?? app.py'],
      tip: 'Short status: the left column is the staging area, the right column is the working tree.',
      n: 'Step thirteen: stage one file. git add readme dot md. Now short status shows a green A for added, in the left column, which means staged. app dot py still shows two question marks: untracked. Staging lets you choose exactly what goes into a commit, instead of everything at once.' },
    { sec: 'Your first repository', title: 'What is in the staging area?', cmd: ['$ git ls-files --stage', '100644 a00621bb3a9b990ee018f8d04c2d3140800d6ca6 0	README.md', '100644 17ae38c7430ff2230bfe9084648cf74536dbd629 0	app.py', '$ git diff --staged --name-only', 'README.md'],
      tip: 'The index is a real file: .git/index. It lists every tracked path and the blob it points to.',
      n: 'Step fourteen: the staging area is real, and you can look at it. ls files dash dash stage prints every tracked file with its mode, the ID of the content blob, and its path. That list lives in one binary file, dot git slash index. When you commit, Git simply turns this list into a tree. Diff staged with name only shows which files will change.' },
    { type: 'tree', sec: 'Your first repository', title: 'git commit: save a snapshot', root: 'shop-api/',
      files: [['README.md', 'C', 'in commit b68ff9d'], ['app.py', 'U', 'not committed yet']],
      cmd: ['$ git commit -m "Add README"', '[main (root-commit) b68ff9d] Add README', ' 1 file changed, 1 insertion(+)', ' create mode 100644 README.md', '$ git add app.py && git commit -m "Add app"', '[main a8cf893] Add app'],
      tip: 'Write the message as an instruction: "Add README", not "added stuff".',
      n: 'Step fifteen: commit. git commit, dash m, add readme. Git prints the branch, root commit because it is the first one, and a short commit ID. Then we add and commit app dot py too. Write messages as an instruction, like add readme, so the log reads like a list of actions.' },
    { type: 'tree', sec: 'Your first repository', title: 'Edit a committed file', root: 'shop-api/',
      files: [['README.md', 'C', 'unchanged'], ['app.py', 'M', 'print("hello, shop")']],
      cmd: ['$ git diff', '--- a/app.py', '+++ b/app.py', '@@ -1 +1 @@', '-print("hello")', '+print("hello, shop")'],
      tip: 'git diff shows unstaged changes. git diff --staged shows what will be committed.',
      n: 'Step sixteen: edit a committed file. We change the message in app dot py, and it becomes modified. git diff shows exactly what changed: the minus line is the old text, the plus line is the new. Plain git diff shows unstaged changes. git diff dash dash staged shows what is already staged, which is exactly what your next commit will contain.' },
    { sec: 'Your first repository', title: 'Diffs that are easier to read', cmd: ['$ git diff --word-diff', 'def tax(x):', '    return x * [-0.18-]{+0.12+}', '$ git diff --stat HEAD~3', '$ git diff --color-moved', '$ git difftool --tool=vimdiff'],
      tip: 'Set diff.colorMoved = zebra so moved code is shown differently from new code.',
      n: 'Step seventeen: diffs that are easier to read. Word diff shows only the words that changed, inside the line: the tax rate went from zero point one eight to zero point one two. Dash dash stat summarises a range of commits. Color moved highlights code that was only moved, not changed. And difftool opens a visual comparison in your favourite tool.' },
    { sec: 'Your first repository', title: 'Read the history', cmd: ['$ git log --oneline', 'a8cf893 (HEAD -> main) Add app', 'b68ff9d Add README', '$ git log --stat -1', '$ git show HEAD', '$ git log --since="2 weeks" --author=Kona'],
      tip: 'git log -p shows the patch of every commit. Press q to quit the pager.',
      n: 'Step eighteen: read the history. git log dash dash oneline gives one line per commit, newest first. HEAD arrow main tells you where you are. dash dash stat lists the files each commit touched. git show HEAD shows the latest commit in full. And you can filter by date, by author, or by a word in the message.' },
    { type: 'tree', sec: 'Your first repository', title: '.gitignore: keep junk out', root: 'shop-api/',
      files: [['.gitignore', 'A', 'the rules'], ['.env', 'I', 'secrets'], ['__pycache__/', 'I', 'build output'], ['node_modules/', 'I', 'dependencies'], ['app.py', 'C'], ['debug.log', 'I', '*.log']],
      cmd: ['$ cat .gitignore', '.env', '__pycache__/', 'node_modules/', '*.log', '$ git check-ignore -v debug.log', '.gitignore:4:*.log	debug.log'],
      tip: 'Ignore rules only affect untracked files. Already committed? Run git rm --cached first.',
      n: 'Step nineteen: dot git ignore. List patterns for files Git should never track: environment files with secrets, build output, dependency folders, and logs. Commit the ignore file itself, so the whole team shares it. check ignore with dash v tells you which rule matched. One catch: ignore rules only apply to untracked files. If something is already committed, remove it from the index with git rm dash dash cached.' },
    { type: 'tree', sec: 'Your first repository', title: 'Rename and delete with Git', root: 'shop-api/',
      files: [['src/', ''], ['src/main.py', 'R', 'was app.py'], ['notes.txt', 'D', 'removed'], ['README.md', 'C']],
      cmd: ['$ mkdir src && git mv app.py src/main.py', '$ git rm notes.txt', "rm 'notes.txt'", '$ git status -s', 'R  app.py -> src/main.py', 'D  notes.txt'],
      tip: 'Git detects renames by content similarity, so a plain mv followed by git add also works.',
      n: 'Step twenty: rename and delete. git mv moves app dot py into a source folder, and stages the rename in one step. git rm deletes a file and stages the deletion. Status shows R for renamed and D for deleted. Git actually detects renames by comparing content, so a normal move followed by git add gives the same result.' },
    { sec: 'Your first repository', title: 'Stage part of a file', cmd: ['$ git add -p app.py', '@@ -1,4 +1,6 @@', '+import logging', ' def total(items):', '+    logging.info("total")', 'Stage this hunk [y,n,q,a,d,s,e,?]? s', 'Split into 2 hunks.'],
      tip: 'y stages the hunk, n skips it, s splits it smaller, e lets you edit it.',
      n: 'Step twenty one: stage part of a file. Often one file holds two unrelated changes. git add dash p shows each change, called a hunk, and asks what to do. y stages it, n skips it, s splits it into smaller hunks, and e lets you edit it by hand. This is how you make small, focused commits that are easy to review and easy to revert.' },
    { sec: 'Your first repository', title: 'Good commit messages', items: [['tag', 'Short subject, 50 characters', 'Imperative: "Fix login timeout"'], ['file', 'Blank line, then the why', 'Wrap the body at 72'], ['link', 'Reference the ticket', 'Fixes #142'], ['check', 'Conventional Commits', 'feat:, fix:, docs:, chore:']],
      tip: 'Conventional Commits let tools generate changelogs and version numbers automatically.',
      n: 'Step twenty two: write good commit messages. A short subject, around fifty characters, written as an instruction. A blank line. Then a body explaining why, not what, because the diff already shows what. Reference the ticket number. Many teams use conventional commits: a prefix like feat, fix, or docs. Release tools read those prefixes to generate changelogs and version numbers automatically.' },
    { sec: 'Your first repository', title: 'Format the log your way', cmd: ['$ git log --format="%h %an %ar %s"', '2279387 Kona Srinivas 6 hours ago Lower tax rate', '0f35939 Kona Srinivas 6 hours ago Add total and tax', '$ git shortlog -sn', '     4	Kona Srinivas', '$ git log --merges --oneline'],
      tip: '%h short ID · %an author · %ar relative date · %s subject. See git help log for all of them.',
      n: 'Step twenty three: format the log your way. Dash dash format accepts placeholders: percent h for the short ID, a n for the author, a r for a relative date, and s for the subject. shortlog dash s n counts commits per author, which is useful for release notes. And dash dash merges lists only merge commits.' },

    // ---------------------------------------------------------------- Undoing changes
    { sec: 'Undoing changes', title: 'Which undo do I need?', cols: ['Situation', 'Command'],
      rows: [['Throw away edits', 'git restore app.py'], ['Unstage, keep the edit', 'git restore --staged app.py'], ['Fix the last commit', 'git commit --amend'], ['Undo a pushed commit', 'git revert <commit>'], ['Move a branch back', 'git reset <commit>  (local only)'], ['Recover "lost" work', 'git reflog']],
      tip: 'Pushed already? Use revert. Not pushed? reset and amend are fine.',
      n: 'Step twenty four: the undo menu. Throw away edits to a file: git restore. Unstage something but keep the edit: restore dash dash staged. Fix the last commit: amend. Undo a commit that others already have: revert. Move a branch back, on your own machine: reset. And when something seems lost: reflog. The one rule to remember: if it is already pushed, use revert.' },
    { type: 'tree', sec: 'Undoing changes', title: 'git restore: discard or unstage', root: 'shop-api/',
      files: [['app.py', 'M', 'edits you regret'], ['db.py', 'A', 'staged by mistake']],
      cmd: ['$ git restore app.py', '$ git restore --staged db.py', '$ git status -s', '?? db.py', '# app.py is back to the last commit'],
      tip: 'restore without --staged permanently discards uncommitted edits. There is no undo.',
      n: 'Step twenty five: git restore. Restore app dot py, and your edits are thrown away; the file goes back to the last commit. Restore dash dash staged db dot py, and the file leaves the staging area, but your work is kept. Be careful with the first form: uncommitted edits that you discard are gone for good.' },
    { sec: 'Undoing changes', title: 'Amend the last commit', cmd: ['$ git commit -m "Add discout"', '$ git add tests/test_discount.py', '$ git commit --amend -m "Add discount"', '[main 5d36487] Add discount', ' Date: Sun Nov 8 10:00:00 2026 +0530', ' 2 files changed'],
      tip: 'Amend creates a NEW commit with a new ID. Never amend a commit you already pushed.',
      n: 'Step twenty six: amend. You committed with a typo, and forgot a test file. Stage the test, and run commit dash dash amend with the right message. The last commit is replaced. But notice the ID changed: amend creates a new commit. That is fine locally, but never amend something you already pushed, because it rewrites shared history.' },
    { type: 'graph', sec: 'Undoing changes', title: 'git reset: soft, mixed, hard',
      ops: [['c', 'a1f', 'main', 'init'], ['c', 'b2e', 'main', 'feature'], ['c', 'c3d', 'main', 'oops'], ['rm', 'c3d']],
      cmd: ['$ git reset --soft HEAD~1   # keep changes staged', '$ git reset HEAD~1          # keep changes unstaged', '$ git reset --hard HEAD~1   # throw changes away', 'HEAD is now at b2e Add feature'],
      tip: 'soft keeps it staged · mixed (default) keeps it in the folder · hard deletes it.',
      n: 'Step twenty seven: reset moves the branch pointer back. Here, the oops commit is removed from main. The three modes decide what happens to its changes. Soft keeps them staged, ready to commit again. Mixed, the default, keeps them in your files but unstaged. Hard throws them away completely. Use hard only when you are sure.' },
    { type: 'graph', sec: 'Undoing changes', title: 'git revert: undo safely',
      ops: [['c', 'a1f', 'main', 'init'], ['c', 'b2e', 'main', 'bug'], ['c', 'c3d', 'main', 'more work'], ['c', 'r4v', 'main', 'Revert bug']],
      cmd: ['$ git revert b2e', '[main 8fb8416] Revert "Add bug"', '$ git revert -m 1 <merge-commit>  # undo a merge'],
      tip: 'Revert adds a new commit. History is never rewritten, so it is safe after a push.',
      n: 'Step twenty eight: revert. The bug commit is already pushed, and other work is on top. Revert does not delete anything. It adds a new commit that does the exact opposite of the bug commit. History stays intact, so it is always safe on shared branches. To revert a merge, add dash m one, which tells Git which side to keep.' },
    { sec: 'Undoing changes', title: 'git reflog: your safety net', cmd: ['$ git reset --hard HEAD~1', 'HEAD is now at 062f5fa Merge branch ...', '$ git reflog -3', '062f5fa HEAD@{0}: reset: moving to HEAD~1', 'e021e63 HEAD@{1}: commit: Oops', '$ git reset --hard e021e63   # it is back'],
      tip: 'The reflog keeps every position HEAD has been at, for about 90 days, locally.',
      n: 'Step twenty nine: the reflog, your safety net. We did a hard reset and lost a commit. Or did we? git reflog lists every place HEAD has pointed, including the commit we just dropped. Reset back to that ID, and the work returns. The reflog lives only on your machine and keeps entries for about ninety days, so commits are rarely truly lost.' },
    { type: 'tree', sec: 'Undoing changes', title: 'git stash: put work aside', root: 'shop-api/',
      files: [['app.py', 'M', 'half-finished'], ['notes.md', 'U', 'new']],
      cmd: ['$ git stash push -u -m "wip discount"', 'Saved working directory and index state On main: wip discount', '$ git stash list', 'stash@{0}: On main: wip discount', '$ git switch hotfix   # fix something urgent', '$ git switch main && git stash pop'],
      tip: '-u includes untracked files. git stash apply keeps the stash; pop removes it.',
      n: 'Step thirty: stash. You are halfway through a change when an urgent bug arrives. git stash push saves your modified files, and dash u includes untracked ones, then leaves a clean folder. Fix the bug on another branch. Come back and run stash pop to restore your work. Apply does the same, but keeps the stash, in case you need it again.' },
    { sec: 'Undoing changes', title: 'git clean: remove untracked files', cmd: ['$ git clean -n', 'Would remove build/', 'Would remove debug.log', '$ git clean -fd', 'Removing build/', 'Removing debug.log'],
      tip: 'Always run -n (dry run) first. clean deletes files that Git never saved.',
      n: 'Step thirty one: git clean removes untracked files and folders, like build output. Always start with dash n, a dry run that only lists what would go. Then dash f d removes files and directories. Be careful: these files were never committed, so Git cannot bring them back.' },
    { sec: 'Undoing changes', title: 'More stash tricks', cmd: ['$ git stash show --stat', ' README.md | 1 +', '$ git stash branch wip-readme', "Switched to a new branch 'wip-readme'", '$ git stash push -m "only css" -- styles/', '$ git stash drop stash@{1}'],
      tip: 'stash branch is the safest way back if the stash no longer applies cleanly.',
      n: 'Step thirty two: more stash tricks. stash show with stat lists the files inside a stash. stash branch creates a new branch from the commit where you stashed, and applies it there, which avoids conflicts if main has moved on. You can stash only one folder by adding a path after two dashes. And drop deletes a stash you no longer need.' },
    { sec: 'Undoing changes', title: 'Restore a file from any commit', cmd: ['$ git restore --source=HEAD~3 app.py', '$ git show v1.0.0:app.py > /tmp/app-v1.py', '$ git log --diff-filter=D --name-only -- "*.py"', '$ git restore --source=<commit>^ deleted.py'],
      tip: 'The caret ^ means "the parent of". Use it to restore a file from just before it was deleted.',
      n: 'Step thirty three: bring back one file from any point in history. restore with dash dash source equals HEAD tilde three takes app dot py as it was three commits ago, without touching anything else. git show, with a tag, a colon and a path, prints an old version to a file. To recover a deleted file, find the deleting commit with diff filter D, then restore from its parent, written with a caret.' },

    // ---------------------------------------------------------------- Branching and merging
    { sec: 'Branching & merging', title: 'What a branch really is', cmd: ['$ cat .git/refs/heads/main', 'a8cf8936c1e4b2d7f0e9a3b5c6d7e8f9a0b1c2d3', '$ cat .git/HEAD', 'ref: refs/heads/main', '$ git branch -v', '* main a8cf893 Add app'],
      tip: 'A branch is a file holding one commit ID. HEAD says which branch you are on.',
      n: 'Step thirty four: what is a branch, really? Look inside dot git. The main branch is a tiny file containing one commit ID. That is all. HEAD is another file that says which branch you are on. Creating a branch just writes a new forty one byte file, which is why Git branches are instant, and why you should use them freely.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Create and switch branches',
      ops: [['c', 'a1f', 'main', 'init'], ['c', 'b2e', 'main', 'readme'], ['co', 'feature/discount'], ['c', 'c3d', 'feature/discount', 'discount'], ['c', 'd4c', 'feature/discount', 'tests']],
      cmd: ['$ git switch -c feature/discount', "Switched to a new branch 'feature/discount'", '$ git commit -am "Add discount"', '$ git branch', '* feature/discount', '  main'],
      tip: 'git switch -c creates and switches. The older git checkout -b does the same.',
      n: 'Step thirty five: create and switch. git switch dash c feature slash discount creates the branch and moves HEAD to it. New commits now move only the feature label forward, while main stays where it was. git switch was added to make branching clearer; the older checkout dash b still works and does the same thing.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Fast-forward merge',
      ops: [['c', 'a1f', 'main', 'init'], ['co', 'feature'], ['c', 'b2e', 'feature', 'login'], ['c', 'c3d', 'feature', 'tests'], ['co', 'main'], ['ff', 'main', 'feature']],
      cmd: ['$ git switch main', '$ git merge feature', 'Updating a1f..c3d', 'Fast-forward', ' login.py | 12 ++++++++++++'],
      tip: 'If main has not moved, Git just slides the label forward. No merge commit.',
      n: 'Step thirty six: the fast forward merge. Main has not changed since we branched. So when we merge, Git does not need to combine anything. It simply slides the main label forward to the feature commit. The output says fast forward. No new commit is created, and history stays a straight line.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Three-way merge',
      ops: [['c', 'a1f', 'main', 'init'], ['co', 'feature'], ['c', 'b2e', 'feature', 'discount'], ['co', 'main'], ['c', 'c3d', 'main', 'rounding'], ['m', 'd4m', 'feature', 'Merge']],
      cmd: ['$ git merge feature', "Merge made by the 'ort' strategy.", '$ git log --oneline --graph', '*   062f5fa Merge branch feature', '|\\', '| * 5d36487 Add discount', '* | 3881f59 Round total', '|/'],
      tip: 'A merge commit has two parents. --no-ff forces one even when a fast-forward is possible.',
      n: 'Step thirty seven: the three way merge. This time both branches moved. Git finds their common ancestor, compares both sides against it, and combines the changes into a new merge commit with two parents. The default strategy is called ort. Some teams always use dash dash no f f, so every feature appears as its own merge in the history.' },
    { type: 'tree', sec: 'Branching & merging', title: 'A merge conflict, step by step', root: 'shop/',
      files: [['app.py', 'X', 'both branches changed line 2'], ['README.md', 'C']],
      cmd: ['$ git merge feature/discount', 'CONFLICT (content): Merge conflict in app.py', '$ cat app.py', '<<<<<<< HEAD', '    return round(sum(items), 2)', '=======', '    return sum(items) - discount', '>>>>>>> feature/discount'],
      tip: 'Between <<<<<<< and ======= is your side. Between ======= and >>>>>>> is theirs.',
      n: 'Step thirty eight: a merge conflict. Main rounded the total, and the feature subtracted a discount, on the same line. Git cannot choose, so it stops and marks the file. Between the less than signs and the equals signs is your side, from HEAD. Between the equals and the greater than signs is the incoming branch. A conflict is not an error. It is Git asking you to decide.' },
    { sec: 'Branching & merging', title: 'Resolve the conflict', cmd: ['# keep both ideas:', '    return round(sum(items) - discount, 2)', '$ git add app.py', '$ git commit --no-edit', '[main 062f5fa] Merge branch feature/discount', '$ git merge --abort   # or give up and start again'],
      tip: 'Turn on rerere: git config --global rerere.enabled true, so Git reuses your resolutions.',
      n: 'Step thirty nine: resolve it. Edit the file, remove the markers, and write what you actually want; here, we keep both ideas, subtract the discount and round. Then git add marks it resolved, and commit finishes the merge. If it gets messy, merge dash dash abort puts everything back. Enable rerere, and Git remembers how you solved a conflict and replays it next time.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Rebase: replay your commits',
      ops: [['c', 'a1f', 'main', 'init'], ['co', 'feature'], ['c', 'c3d', 'feature', 'login'], ['c', 'd4c', 'feature', 'tests'], ['co', 'main'], ['c', 'e5b', 'main', 'hotfix'], ['co', 'feature'], ['rb', 'feature', 'main']],
      cmd: ['$ git switch feature', '$ git rebase main', 'Successfully rebased and updated refs/heads/feature.'],
      tip: 'Rebase creates new commits with new IDs. The old ones are left behind.',
      n: 'Step forty: rebase. Feature has login and tests, and main moved on with a hotfix. Instead of merging, rebase takes your feature commits and replays them, one by one, on top of the new main. The result is a straight line, as if you had started your work today. But see the crossed out circles: these are new commits with new IDs.' },
    { type: 'graph', sec: 'Branching & merging', title: 'rebase --onto: a new base',
      ops: [['c', 'a1f', 'main', 'init'], ['co', 'part1'], ['c', 'b2e', 'part1', 'part 1'], ['co', 'topic'], ['c', 'c3d', 'topic', 'topic'], ['co', 'main'], ['c', 'd4c', 'main', 'main moves'], ['co', 'topic'], ['rb', 'topic', 'main']],
      cmd: ['$ git rebase --onto main part1 topic', 'Successfully rebased and updated refs/heads/topic.', '$ git log --oneline -3 topic', 'e2a827a Topic', 'c0481c5 Main moves'],
      tip: 'Read it as: take the commits of topic that are not in part1, and replay them onto main.',
      n: 'Step forty one: rebase onto. Topic was started from part one by mistake, and should depend only on main. Rebase dash dash onto main, part one, topic, takes the commits that are on topic but not on part one, and replays them onto main. Part one stays behind. This is how you untangle a branch that was built on the wrong base.' },
    { sec: 'Branching & merging', title: 'Stacked branches with --update-refs', cmd: ['$ git switch part2', '$ git rebase --update-refs main', 'Successfully rebased and updated refs/heads/part2.', 'Updated the following refs with --update-refs:', '	refs/heads/part1', '$ git config --global rebase.updateRefs true'],
      tip: 'Split big features into a stack of small pull requests, and keep them all up to date with one rebase.',
      n: 'Step forty two: stacked branches. A big feature is split into part one and part two, each its own small pull request, with part two built on part one. When main moves, rebase part two with dash dash update refs, and Git moves part one too, in the same operation. Turn it on by default, and stacks of small pull requests become easy to maintain.' },
    { sec: 'Branching & merging', title: 'Merge or rebase?', cols: ['', 'Merge', 'Rebase'],
      rows: [['History', 'True record, with merge commits', 'Clean straight line'], ['Commit IDs', 'Unchanged', 'Rewritten'], ['Conflicts', 'Resolved once', 'Possibly once per commit'], ['Shared branches', 'Always safe', 'Only your own branch']],
      tip: 'The golden rule: never rebase commits that other people have already pulled.',
      n: 'Step forty three: merge or rebase? Merge keeps a true record, including when branches joined, and never changes commit IDs. Rebase gives a clean straight line, but rewrites IDs, and you may resolve conflicts once per commit. Both are fine. The golden rule: never rebase commits that other people already have. Rebase your own branch; merge into shared ones.' },
    { sec: 'Branching & merging', title: 'Pick a side in a conflict', cmd: ['$ git merge x', 'CONFLICT (content): Merge conflict in app.py', '$ git checkout --theirs app.py && grep "return x" app.py', '    return x * 0.05', '$ git checkout --ours app.py && grep "return x" app.py', '    return x * 0.20', '$ git merge -X theirs x   # prefer theirs for every conflict'],
      tip: 'Careful: during a REBASE, ours and theirs are swapped, because your commits are being replayed.',
      n: 'Step forty four: sometimes you just want one side of a conflict. checkout dash dash theirs takes the incoming branch version of the file, here a rate of zero point zero five. Dash dash ours keeps your version. dash X theirs applies that preference to every conflict in the merge. One trap: during a rebase, ours and theirs are swapped, because Git is replaying your commits onto the other branch.' },
    { sec: 'Branching & merging', title: 'Squash merges', cols: ['Merge style', 'Result on main', 'Use when'],
      rows: [['Merge commit', 'Every commit plus a merge', 'You want the full story'], ['Squash and merge', 'One commit per pull request', 'Messy work-in-progress commits'], ['Rebase and merge', 'Every commit, no merge commit', 'Clean, meaningful commits']],
      tip: 'git merge --squash feature stages everything as one change; then you commit it yourself.',
      n: 'Step forty five: the three buttons on a pull request. A merge commit keeps every commit, plus a merge. Squash and merge turns the whole pull request into one commit on main, which hides messy work in progress commits. Rebase and merge replays every commit with no merge commit. On the command line, merge dash dash squash stages everything as one change for you to commit.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Cherry-pick one commit',
      ops: [['c', 'a1f', 'main', 'init'], ['co', 'hotfix'], ['c', 'b2e', 'hotfix', 'fix tax'], ['c', 'c3d', 'hotfix', 'debug'], ['co', 'main'], ['c', "b2e'", 'main', 'fix tax']],
      cmd: ['$ git switch main', '$ git cherry-pick b2e', '[main d4463d4] Fix tax rounding', '$ git cherry-pick -x b2e   # notes the origin'],
      tip: 'Cherry-pick copies a commit. Use it for hotfixes and backports, not as a daily workflow.',
      n: 'Step forty six: cherry pick. The hotfix branch has a tax fix, and a debug commit you do not want. Cherry pick copies just the one fix onto main, as a new commit. Dash x adds a note saying where it came from, which is handy for backports to release branches. Use it for those cases, not as a replacement for merging.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Tags mark releases',
      ops: [['c', 'a1f', 'main', 'init'], ['c', 'b2e', 'main', 'feature'], ['tag', 'v1.0.0', 'b2e'], ['c', 'c3d', 'main', 'fix'], ['tag', 'v1.0.1', 'c3d']],
      cmd: ['$ git tag -a v1.0.0 -m "First release"', '$ git tag', 'v1.0.0', '$ git describe', 'v1.0.0-3-gd4463d4', '$ git push origin v1.0.0'],
      tip: 'Use annotated tags (-a) for releases: they store the author, date and a message.',
      n: 'Step forty seven: tags. A tag is a permanent name for one commit, like a release version. Annotated tags, with dash a, store who tagged it, when, and a message, so use them for releases. git describe tells you how far you are from the last tag: three commits after v one. Tags are not pushed automatically, so push them on purpose.' },
    { sec: 'Branching & merging', title: 'Tag types and semantic versions', cols: ['', 'Lightweight', 'Annotated'],
      rows: [['Create', 'git tag v1.2.0', 'git tag -a v1.2.0 -m "..."'], ['Stores', 'Only a name', 'Author, date, message, signature'], ['Shown by git describe', 'Only with --tags', 'Always'], ['Use for', 'Private bookmarks', 'Releases']],
      tip: 'Semantic versioning: MAJOR.MINOR.PATCH. Breaking change, new feature, bug fix.',
      n: 'Step forty eight: two kinds of tags. A lightweight tag is only a name. An annotated tag is a full object, storing the author, date, message, and optionally a signature, and git describe uses it by default. Use annotated tags for releases, with semantic versions: major for breaking changes, minor for new features, and patch for bug fixes.' },
    { type: 'graph', sec: 'Branching & merging', title: 'Detached HEAD',
      ops: [['c', 'a1f', 'main', 'init'], ['c', 'b2e', 'main', 'v1'], ['c', 'c3d', 'main', 'v2'], ['co', 'detached'], ['ff', 'detached', 'b2e'], ['c', 'x9z', 'detached', 'experiment']],
      cmd: ['$ git switch --detach v1.0.0', 'HEAD is now at b2e Add feature', '$ git switch -c experiment   # keep this work'],
      tip: 'Commits made while detached belong to no branch. Create one before you switch away.',
      n: 'Step forty nine: detached HEAD. When you check out a tag or a commit ID directly, HEAD points at a commit instead of a branch. You can look around and even commit, but those commits belong to no branch, and become hard to find once you leave. If you want to keep them, create a branch right away with switch dash c.' },

    // ---------------------------------------------------------------- Remotes
    { sec: 'Remotes & teamwork', title: 'Remotes: other copies of the repo', nodes: [['monitor', 'Your laptop', 'main, feature'], ['cloud', 'origin', 'GitHub'], ['users', 'upstream', 'the original project']], edges: ['push / fetch', 'fork of'],
      cmd: ['$ git remote add origin git@github.com:kona/shop-api.git', '$ git remote -v', 'origin  git@github.com:kona/shop-api.git (fetch)', 'origin  git@github.com:kona/shop-api.git (push)'],
      n: 'Step fifty: remotes. A remote is just a named address of another copy of the repository. origin is, by convention, the one you cloned from or push to, often on GitHub. When you contribute to someone else project through a fork, the original is usually called upstream. git remote dash v lists them.' },
    { sec: 'Remotes & teamwork', title: 'Clone, push and track', cmd: ['$ git clone https://github.com/kona/shop-api.git', '$ git push -u origin main', 'branch main set up to track origin/main.', '$ git status -sb', '## main...origin/main [ahead 2]'],
      tip: '-u sets the upstream once. After that, plain git push and git pull know where to go.',
      n: 'Step fifty one: clone and push. Clone downloads the whole history and sets up origin. When you push a new branch, use dash u: it links your local branch to the remote one, so later you can just type git push. status dash s b then shows if you are ahead or behind the remote, here two commits ahead.' },
    { sec: 'Remotes & teamwork', title: 'Fetch vs pull', nodes: [['cloud', 'origin/main', 'on GitHub'], ['database', 'origin/main', 'your copy of it'], ['git', 'main', 'your branch']], edges: ['git fetch', 'merge or rebase'],
      cmd: ['$ git fetch origin', '$ git log --oneline main..origin/main', '$ git pull --rebase', '$ git pull --ff-only'],
      tip: 'pull = fetch + merge (or rebase). Fetch first if you want to look before you change anything.',
      n: 'Step fifty two: fetch versus pull. Fetch downloads new commits and updates your remote tracking branches, like origin slash main, but never touches your own work. Pull is fetch plus a merge or a rebase into your current branch. Fetch first when you want to look before changing anything: main dot dot origin slash main lists what is new.' },
    { sec: 'Remotes & teamwork', title: 'Clean up branches', cmd: ['$ git branch --merged main', '  feature/discount', '$ git branch -d feature/discount', '$ git push origin --delete feature/discount', '$ git fetch --prune', '$ git config --global fetch.prune true'],
      tip: 'Lowercase -d refuses to delete unmerged work. Uppercase -D forces it.',
      n: 'Step fifty three: tidy up. branch dash dash merged lists branches already merged into main, which are safe to delete. Lowercase dash d deletes a local branch, but refuses if it holds unmerged work, while capital D forces it. push with dash dash delete removes the remote branch. And fetch with prune removes stale remote tracking branches; set it as the default.' },
    { sec: 'Remotes & teamwork', title: 'SSH keys and safe force-push', cmd: ['$ ssh-keygen -t ed25519 -C "kona@example.com"', '$ ssh -T git@github.com', 'Hi kona! You have successfully authenticated.', '$ git push --force-with-lease', '# refuses if someone else pushed in the meantime'],
      tip: 'Never use plain --force on a shared branch. --force-with-lease protects other people\'s work.',
      n: 'Step fifty four: authentication and force push. Create an ed25519 SSH key, add the public part to GitHub, and test it. Or use HTTPS with a credential manager. After a rebase you need to force push your branch, but never use plain dash dash force. Force with lease refuses if someone else pushed in the meantime, so you cannot wipe out their work by accident.' },
    { sec: 'Remotes & teamwork', title: 'Pull requests', nodes: [['git', 'Push a branch', 'feature/discount'], ['comment', 'Open a PR', 'describe the why'], ['check', 'CI + review', 'tests, approvals'], ['route', 'Merge', 'merge, squash or rebase']], edges: ['', '', ''],
      tip: 'Keep pull requests small: under 400 changed lines get far better reviews.',
      n: 'Step fifty five: the pull request, or merge request on GitLab. Push your branch, open a pull request, and describe why the change is needed. Automated checks run, and teammates review. Then it is merged, using a merge commit, a squash, or a rebase, depending on the repository settings. Small pull requests get far better reviews than giant ones.' },
    { sec: 'Remotes & teamwork', title: 'Fork and stay in sync', cmd: ['$ git clone git@github.com:kona/project.git', '$ git remote add upstream https://github.com/owner/project.git', '$ git fetch upstream', '$ git rebase upstream/main', '$ git push --force-with-lease origin my-fix'],
      tip: 'Practice this with the first-contributions repository on GitHub.',
      n: 'Step fifty six: contributing to open source. Fork the project on GitHub, clone your fork, and add the original as upstream. Before you open a pull request, fetch upstream, and rebase your branch on its main, so your change applies cleanly. Then push to your fork with force with lease. The first contributions repository is a great place to practise.' },
    { sec: 'Remotes & teamwork', title: 'CODEOWNERS and PR templates', cmd: ['# .github/CODEOWNERS', '*              @kona/platform', '/infra/        @kona/sre', '*.tf           @kona/sre', '# .github/pull_request_template.md', '## What and why', '## How tested'],
      tip: 'The last matching rule wins. Owners are added as reviewers automatically.',
      n: 'Step fifty seven: code owners and templates. A code owners file maps paths to teams. Here, the platform team owns everything by default, and the S R E team owns the infra folder and every Terraform file; the last matching rule wins. Owners are requested as reviewers automatically. A pull request template pre fills every description with what, why, and how it was tested.' },
    { sec: 'Remotes & teamwork', title: 'Protect your main branch', items: [['shield', 'Require pull requests', 'No direct pushes to main'], ['check', 'Require passing checks', 'Tests, lint, security scans'], ['users', 'Require reviews and CODEOWNERS', 'The right people approve'], ['lock', 'Block force-push and deletion', 'History stays trustworthy']],
      tip: 'On GitHub these are rulesets; on GitLab, protected branches; on Azure Repos, branch policies.',
      n: 'Step fifty eight: protect main. Require a pull request for every change, with no direct pushes. Require the tests and scans to pass. Require reviews, and use a code owners file so the right people approve changes to their area. And block force pushes and deletion. GitHub calls these rulesets, GitLab calls them protected branches, and Azure Repos calls them branch policies.' },

    // ---------------------------------------------------------------- Rewriting history
    { sec: 'Rewriting history', title: 'Interactive rebase', cmd: ['$ git rebase -i HEAD~4', 'pick   3a1f Add discount', 'squash 9c2e Fix typo', 'reword 4b7d Add tests', 'drop   e8f0 Debug print', '# p pick · r reword · e edit · s squash · f fixup · d drop'],
      tip: 'Clean up your own branch before the pull request. Never on shared history.',
      n: 'Step fifty nine: interactive rebase, the most powerful clean up tool. Rebase dash i HEAD tilde four opens your last four commits in an editor. Change pick to squash to fold a commit into the one above. Reword changes a message. Edit stops so you can change the content. Drop deletes a commit. Save, and Git rebuilds the branch exactly as you described.' },
    { sec: 'Rewriting history', title: 'Fixup commits and autosquash', cmd: ['$ git commit --fixup=3a1f', '[feat2 7d21] fixup! Add discount', '$ git rebase -i --autosquash main', 'Successfully rebased and updated refs/heads/feat2.', '$ git config --global rebase.autoSquash true'],
      tip: 'Make fixups during review, then autosquash them away before merging.',
      n: 'Step sixty: fixup commits. During review, someone asks for a small change to an earlier commit. Commit it with dash dash fixup equals that commit ID. Git names it fixup, followed by the original message. Later, rebase with dash dash autosquash, and Git moves each fixup next to its target and folds it in automatically. Set it as the default, and you never think about it again.' },
    { sec: 'Rewriting history', title: 'git history: the new experimental command', cmd: ['$ git history reword HEAD~2', '$ git history fixup HEAD~1', '$ git history split HEAD -- src/', '$ git history squash HEAD~3..HEAD', '$ git history drop HEAD~1 --dry-run'],
      tip: 'Added in Git 2.54 and still EXPERIMENTAL in 2.56: options may change. Interactive rebase still works.',
      n: 'Step sixty one: something new. Git two point five four added an experimental command called git history, and it keeps growing. Reword changes a message, fixup folds staged changes into an earlier commit, split breaks one commit into two, and the newest subcommands, squash and drop, arrived in two point five six. It is still marked experimental, so options may change; interactive rebase remains the stable way.' },
    { sec: 'Rewriting history', title: 'Remove a secret from all history', cmd: ['$ pip install git-filter-repo', '$ git filter-repo --path .env --invert-paths', '$ git filter-repo --replace-text expressions.txt', '$ git push --force-with-lease --all', '# then ROTATE the leaked key'],
      tip: 'Rewriting history does not un-leak a secret. Rotate the key first, always.',
      n: 'Step sixty two: a secret was committed, and pushed. First, and most important, rotate the key, because anyone may already have copied it. Then clean the history with git filter repo, the tool the Git project recommends instead of filter branch. Invert paths removes a file from every commit, and replace text scrubs strings. Finally, force push, and ask everyone to clone again.' },

    // ---------------------------------------------------------------- Inspecting
    { sec: 'Inspect & debug', title: 'Search history like a detective', cmd: ['$ git log -S "discount" --oneline', '5d36487 Add discount', '$ git log -G "def total\\(" -p', '$ git log --follow -- src/main.py', '$ git log main..feature', '$ git diff main...feature --stat'],
      tip: 'Two dots: commits in one but not the other. Three dots in diff: changes since the branches split.',
      n: 'Step sixty three: search history. Log dash S finds commits that added or removed a word, here the commit that introduced discount. Dash G searches with a regular expression. Dash dash follow tracks a file across renames. Main dot dot feature lists commits on feature that are not on main. And diff with three dots shows only what changed on feature since it split from main.' },
    { sec: 'Inspect & debug', title: 'git blame: who changed this line, and why', cmd: ['$ git blame -s app.py', '5d364872 1) def total(items, discount=0):', '062f5fa1 2)     return round(sum(items) - discount, 2)', '$ git blame -w -C -C app.py', '$ git config blame.ignoreRevsFile .git-blame-ignore-revs'],
      tip: 'Use it to find the commit and its reason, not to blame people.',
      n: 'Step sixty four: git blame shows, for every line, the commit that last changed it. Then git show that commit to read why. Dash w ignores whitespace changes, and dash C twice follows code that was moved or copied between files. If a big formatting commit pollutes the results, list it in an ignore revs file. Despite the name, use it to find reasons, not to blame people.' },
    { sec: 'Inspect & debug', title: 'Trace one function through history', cmd: ['$ git log -L "/def tax/,+1:app.py" --oneline', '0f35939 Add total and tax', '+def tax(x):', '+    return x * 0.18', '$ git grep -n "def "', 'app.py:1:def total(items):', 'app.py:4:def tax(x):'],
      tip: 'git grep searches tracked files only, and can search any commit: git grep tax HEAD~5.',
      n: 'Step sixty five: trace one function. log dash L, with a pattern and a file, shows every commit that changed just the tax function, with its diff. git grep searches tracked files, much faster than plain grep in a big repository, and it can search any older commit by adding its name. Together they answer the question: how did this code get like this?' },
    { type: 'graph', sec: 'Inspect & debug', title: 'git bisect: find the bad commit',
      ops: [['c', 'g01', 'main', 'good'], ['c', 'g02', 'main', ''], ['c', 'g03', 'main', 'test'], ['c', 'b04', 'main', 'bug!'], ['c', 'b05', 'main', 'test'], ['c', 'b06', 'main', 'bad']],
      cmd: ['$ git bisect start HEAD v1.0.0', 'Bisecting: 2 revisions left to test after this (roughly 2 steps)', '$ git bisect run ./test.sh', 'b04 is the first bad commit', '$ git bisect reset'],
      tip: 'Binary search: 1,000 commits take only about 10 tests.',
      n: 'Step sixty six: git bisect. Something broke, and you know a version where it worked. Start bisect with the bad and the good commit. Git checks out the commit in the middle, and you test it: good or bad. Each answer halves the search. Better still, bisect run with a test script does it automatically. A thousand commits need only about ten tests.' },
    { sec: 'Inspect & debug', title: 'Compare two versions of a branch', cmd: ['$ git range-diff main~1..part1 main..part1', '1:  5e9f78f = 1:  5e9f78f Part 1', '$ git notes add -m "Reviewed by Asha" HEAD', '$ git log -1 --format="%s%n  note: %N"', 'main rate', '  note: Reviewed by Asha'],
      tip: 'range-diff shows what changed between two versions of the same pull request after a rebase.',
      n: 'Step sixty seven: two lesser known tools. range diff compares two versions of the same series of commits, for example a pull request before and after a rebase, and an equals sign means a commit did not change. And notes attach extra information to a commit without changing its ID, such as who reviewed it.' },
    { sec: 'Inspect & debug', title: 'Inside the object database', cmd: ['$ git cat-file -t HEAD', 'commit', '$ git cat-file -p HEAD', 'tree c87837deae275ad49b3db6c3ee2b101fbcf7da1b', 'parent b68ff9d79fef1ee8c34b5b4b39fae23d04e19463', 'author Kona Srinivas <kona@example.com>', '$ git cat-file -p "HEAD^{tree}"', '100644 blob 6ffb96d5…  README.md', '100644 blob 11b15b1a…  app.py'],
      tip: 'Every object is named by the hash of its content. Same content, same name, stored once.',
      n: 'Step sixty eight: look inside the object database. Cat file dash t says HEAD is a commit. Dash p prints it: a pointer to a tree, a pointer to the parent commit, the author, and the message. Print the tree, and you see blobs, which hold file contents. Every object is named by a hash of its content, so identical files are stored only once.' },
    { sec: 'Inspect & debug', title: 'The four object types', nodes: [['git', 'commit', 'snapshot + parent + author'], ['folder', 'tree', 'a directory listing'], ['file', 'blob', 'file content'], ['tag', 'tag', 'annotated name']], edges: ['points to', 'contains', ''],
      tip: 'Branches and tags are just names in .git/refs that point at these objects.',
      n: 'Step sixty nine: there are only four kinds of objects. A commit points to one tree, its parent commits, and records the author and message. A tree is a directory listing, pointing to blobs and other trees. A blob is the content of one file. And an annotated tag points to a commit with a name and message. Everything else, branches included, is just a name pointing at one of these.' },

    // ---------------------------------------------------------------- Config & tooling
    { sec: 'Config & tooling', title: 'Aliases and a better log', cmd: ['$ git config --global alias.st "status -sb"', '$ git config --global alias.lg "log --oneline --graph --decorate --all"', '$ git lg', '*   062f5fa (HEAD -> main) Merge branch feature', '|\\', '| * 5d36487 Add discount'],
      tip: 'Aliases live in ~/.gitconfig, so you can copy them to every machine.',
      n: 'Step seventy: aliases save typing. git st for a short status with branch info. git l g for a graph of every branch, with labels. They are stored in your global config file, so copy that file to every machine you use. A good log alias alone makes branching much easier to understand.' },
    { sec: 'Config & tooling', title: 'Hooks: automate checks', cmd: ['$ cat .git/hooks/pre-commit', '#!/bin/sh', 'ruff check . || exit 1', '$ chmod +x .git/hooks/pre-commit', '$ pip install pre-commit && pre-commit install', 'pre-commit installed at .git/hooks/pre-commit'],
      tip: 'Hooks in .git/hooks are not shared. The pre-commit framework shares them through a config file.',
      n: 'Step seventy one: hooks are scripts that Git runs at certain moments. A pre commit hook can run the linter, and block the commit if it fails. Commit message hooks can enforce a format, and pre push hooks can run tests. Hooks in the dot git folder are not shared with your team, so use the pre commit framework, which installs them from a config file in the repository.' },
    { sec: 'Config & tooling', title: 'Line endings and attributes', cmd: ['# .gitattributes', '* text=auto eol=lf', '*.bat text eol=crlf', '*.png binary', '*.psd filter=lfs diff=lfs merge=lfs -text'],
      tip: 'Commit a .gitattributes file to stop "every line changed" diffs between Windows and Mac.',
      n: 'Step seventy two: line endings. Windows uses carriage return plus line feed, Mac and Linux use only line feed, and mixed teams get diffs where every line changed. A dot git attributes file fixes this for everyone: text equals auto with l f endings, except Windows batch files. You can also mark binary files, and route large files to Git L F S.' },
    { type: 'tree', sec: 'Config & tooling', title: 'Submodules: a repo inside a repo', root: 'shop-api/',
      files: [['.gitmodules', 'A', 'path + URL'], ['libs/', ''], ['libs/payments/', 'A', 'pinned commit 9f2c1ab'], ['app.py', 'C']],
      cmd: ['$ git submodule add https://github.com/acme/payments libs/payments', '$ git clone --recurse-submodules <url>', '$ git submodule update --init --recursive', '$ git submodule update --remote'],
      tip: 'The parent repo stores one commit ID for the submodule, not its files.',
      n: 'Step seventy three: submodules put one repository inside another. The parent records the submodule path and URL in dot git modules, and pins it to one exact commit. Clone with recurse submodules, or run submodule update init afterwards. Submodules are powerful but easy to get wrong; for shared libraries, a package manager is often simpler.' },
    { sec: 'Config & tooling', title: 'Sign your commits', cmd: ['$ git config --global gpg.format ssh', '$ git config --global user.signingkey ~/.ssh/id_ed25519.pub', '$ git config --global commit.gpgsign true', '$ git log --show-signature -1', 'Good "git" signature for kona@example.com'],
      tip: 'Upload the same key to GitHub as a signing key to get the Verified badge.',
      n: 'Step seventy four: sign your commits. Anyone can set any name and email, so signing proves a commit really came from you. You can sign with your existing SSH key: set the format to s s h, point to your public key, and turn signing on for every commit. Add the key to GitHub as a signing key, and your commits show a verified badge.' },

    // ---------------------------------------------------------------- Large repositories
    { sec: 'Large repositories', title: 'Shallow, partial and sparse', cols: ['Technique', 'Command', 'Saves'],
      rows: [['Shallow clone', 'git clone --depth 1', 'Old history (great for CI)'], ['Partial clone', 'git clone --filter=blob:none', 'File contents until needed'], ['Sparse checkout', 'git sparse-checkout set apps/web', 'Files outside your folders'], ['Scalar', 'scalar clone <url>', 'All of the above, tuned']],
      tip: 'For CI, a shallow clone often cuts checkout time from minutes to seconds.',
      n: 'Step seventy five: huge repositories. A shallow clone, depth one, downloads only the latest commit, which is perfect for CI. A partial clone with a blob none filter gets the full history but fetches file contents only when needed. Sparse checkout puts only your folders on disk, which is ideal in a monorepo. And scalar, which ships with Git, sets all of this up for you.' },
    { type: 'tree', sec: 'Large repositories', title: 'Worktrees: two branches at once', root: '~/code/',
      files: [['shop/', '', 'main'], ['shop/.git/', 'I', 'one repository'], ['shop-hotfix/', '', 'hotfix-2 branch'], ['shop-hotfix/.git', 'I', 'a file pointing back']],
      cmd: ['$ git worktree add ../shop-hotfix -b hotfix-2', "Preparing worktree (new branch 'hotfix-2')", '$ git worktree list', 'shop        1527f8f [main]', 'shop-hotfix 1527f8f [hotfix-2]', '$ git worktree remove ../shop-hotfix'],
      tip: 'No stash, no second clone: each worktree has its own folder and branch, sharing one history.',
      n: 'Step seventy six: worktrees. Instead of stashing, or cloning a second copy, add a worktree: a second folder with its own branch, sharing the same repository. Fix the hotfix in one folder while your feature build keeps running in the other. Worktree list shows them all, and remove cleans up when you are done.' },
    { sec: 'Large repositories', title: 'Git LFS for big binary files', cmd: ['$ git lfs install', '$ git lfs track "*.psd" "*.mp4"', 'Tracking "*.psd"', '$ git add .gitattributes design.psd', '$ git lfs ls-files', 'a1b2c3d4 * design.psd'],
      tip: 'Git stores a tiny pointer; the real file lives on the LFS server and downloads on checkout.',
      n: 'Step seventy seven: large binary files, like videos and design files, bloat a repository forever, because every version is kept. Git L F S stores only a small pointer in Git, and keeps the real file on a separate server. Track the patterns, which writes them to git attributes, then add and commit as usual. Everyone gets the files on checkout.' },
    { sec: 'Large repositories', title: 'Keep the repository fast', cmd: ['$ git count-objects -vH', 'count: 50  size: 200.00 KiB', '$ git maintenance start', '$ git gc', '$ git count-objects -vH | grep size-pack', 'size-pack: 7.57 KiB'],
      tip: 'git maintenance start schedules background housekeeping, so you rarely run gc by hand.',
      n: 'Step seventy eight: housekeeping. Count objects shows loose objects using space; here fifty of them use two hundred kilobytes. Garbage collection packs them, and the same data drops to under eight kilobytes. git maintenance start schedules this in the background, along with prefetching and commit graph updates, so big repositories stay fast without manual effort.' },
    { sec: 'Large repositories', title: 'Bundles and archives', cmd: ['$ git bundle create shop.bundle --all', '$ git bundle verify shop.bundle', 'The bundle uses this hash algorithm: sha1', '$ git clone shop.bundle shop-copy', '$ git archive --format=zip -o shop-v1.zip v1.2.0'],
      tip: 'A bundle is a whole repository in one file: perfect for air-gapped networks and backups.',
      n: 'Step seventy nine: move repositories without a server. A bundle packs the whole repository, every branch and tag, into a single file. Verify it, copy it on a USB drive into an air gapped network, and clone from it like a URL. git archive is different: it exports the files of one version, with no history, for example a zip of release one point two.' },

    // ---------------------------------------------------------------- Security
    { sec: 'Security', title: 'Never commit secrets', items: [['key', 'Keep secrets out of the repo', '.env in .gitignore, a vault instead'], ['search', 'Scan before every commit', 'gitleaks in a pre-commit hook'], ['shield', 'Turn on push protection', 'GitHub blocks known key formats'], ['refresh', 'Leaked? Rotate first', 'Then clean history']],
      cmd: ['$ gitleaks git --redact', 'Finding:     aws_secret_access_key = ****', 'RuleID:      aws-access-token', 'Commit:      e8f0a1c', 'leaks found: 1'],
      n: 'Step eighty: secrets. Keep them out of the repository entirely: environment files in git ignore, and real values in a vault or secret manager. Scan before every commit with gitleaks, in a pre commit hook and in CI. Turn on push protection, so GitHub blocks known key formats. And if one leaks, rotate it first, then clean the history.' },
    { sec: 'Security', title: 'Trust and safety settings', cols: ['Setting', 'Protects against'],
      rows: [['safe.directory', 'Repositories owned by another user'], ['commit.gpgsign = true', 'Spoofed author names'], ['transfer.fsckObjects', 'Corrupt or malicious objects'], ['Signed tags for releases', 'Tampered release builds']],
      tip: 'Git 3.0 will tighten safe.bareRepository defaults, blocking a class of hook-based attacks.',
      n: 'Step eighty one: trust settings. Git refuses to work in repositories owned by another user unless you mark them safe, which blocks attacks through shared folders. Signing stops spoofed author names. Transfer f s c k objects checks every object you receive. And signed release tags let your pipeline verify exactly what it is building.' },
    { sec: 'Security', title: 'A secure pre-commit setup', cmd: ['# .pre-commit-config.yaml', 'repos:', '  - repo: https://github.com/gitleaks/gitleaks', '    rev: v8.30.1', '    hooks: [{id: gitleaks}]', '  - repo: https://github.com/pre-commit/pre-commit-hooks', '    rev: v6.0.0', '    hooks: [{id: check-added-large-files}, {id: detect-private-key}]'],
      tip: 'Run the same hooks in CI with pre-commit run --all-files, so nobody can skip them.',
      n: 'Step eighty two: put it together in one config file. The pre commit framework installs gitleaks to catch secrets, plus standard hooks that block large files and private keys. Everyone runs the same checks on every commit. Because anyone can skip local hooks, also run pre commit run all files in CI, which makes the checks mandatory.' },

    // ---------------------------------------------------------------- Workflows & Git 3.0
    { sec: 'Workflows & Git 3.0', title: 'Branching strategies', cols: ['Strategy', 'How it works', 'Best for'],
      rows: [['Trunk-based', 'Merge daily, feature flags', 'Fast CI/CD teams'], ['GitHub flow', 'Branch, PR, merge, deploy main', 'Web apps, continuous deploy'], ['GitFlow', 'develop, release and hotfix branches', 'Versioned, scheduled releases'], ['Release branches', 'Cut release/1.4, cherry-pick fixes', 'Supporting old versions']],
      tip: 'Most DevOps teams today use trunk-based development or GitHub flow.',
      n: 'Step eighty three: branching strategies. Trunk based development keeps branches very short and merges to main every day, hiding unfinished work behind feature flags. GitHub flow is similar: branch, pull request, merge, deploy. GitFlow adds develop, release and hotfix branches, which suits products with scheduled versions. Release branches let you keep fixing older versions.' },
    { type: 'graph', sec: 'Workflows & Git 3.0', title: 'Trunk-based development',
      ops: [['c', 'a1f', 'main', 'v1'], ['co', 'login'], ['c', 'b2e', 'login', 'login'], ['co', 'main'], ['m', 'c3m', 'login', 'merge'], ['co', 'cart'], ['c', 'd4c', 'cart', 'cart'], ['co', 'main'], ['m', 'e5m', 'cart', 'merge'], ['tag', 'v1.1', 'e5m']],
      tip: 'Branches live hours or a day, not weeks. Small merges mean small conflicts.',
      n: 'Step eighty four: trunk based development in pictures. A short branch for login, merged the same day. Another short branch for the cart, merged again. Main is always releasable, and gets tagged when you ship. Because branches live for hours instead of weeks, conflicts stay small, and CI tells you quickly if something broke.' },
    { sec: 'Workflows & Git 3.0', title: 'Git in a CI/CD pipeline', nodes: [['git', 'git push', 'a branch or tag'], ['pipeline', 'CI runs', 'lint, test, scan'], ['box', 'Build artifact', 'tagged with the commit'], ['rocket', 'Deploy', 'GitOps syncs main']], edges: ['webhook', 'on success', 'promote'],
      tip: 'Tag images with the commit SHA. Then every running container traces back to exact code.',
      n: 'Step eighty five: Git drives the whole pipeline. A push triggers a webhook, and CI runs lint, tests and security scans. On success it builds an artifact, tagged with the commit ID, so anything running in production traces back to exact code. With GitOps, tools like Argo CD watch a Git repository and make the cluster match it, so Git becomes the source of truth for deployments too.' },
    { sec: 'Workflows & Git 3.0', title: 'What changes in Git 3.0', items: [['git', 'Default branch: main', 'Instead of master'], ['lock', 'SHA-256 for new repos', 'Instead of SHA-1'], ['database', 'reftable ref storage', 'Faster, atomic, case-safe'], ['trash', 'Old commands removed', 'git whatchanged, grafts']],
      tip: 'Existing repositories keep working. The new defaults apply to newly created repositories.',
      n: 'Step eighty six: Git three point zero is coming. The Git project says version two point nine eight is meant to be one of the last releases before it. New repositories will default to a main branch, will use S H A two five six hashes instead of S H A one, and will store references in the faster reftable format. Some old commands, like whatchanged, are removed. Your existing repositories keep working.' },
    { sec: 'Workflows & Git 3.0', title: 'Try the Git 3.0 defaults today', cmd: ['$ git init --object-format=sha256 --ref-format=reftable demo', '$ git -C demo rev-parse --show-object-format', 'sha256', '$ git -C demo rev-parse --show-ref-format', 'reftable', '$ git refs migrate --ref-format=reftable   # convert a repo'],
      tip: 'Check that your Git host and tools support SHA-256 before using it for real projects.',
      n: 'Step eighty seven: you can try the new defaults right now. git init with object format S H A two five six and ref format reftable creates a repository the Git three way. rev parse confirms both. git refs migrate converts an existing repository to reftable. Before you use S H A two five six for real work, check that your hosting service and tools support it.' },

    { type: 'mistakes', rows: [['git add . without looking', 'git status, then git add -p'], ['Committing secrets or .env files', '.gitignore + gitleaks pre-commit'], ['Rebasing or amending pushed commits', 'Only rewrite your own branch'], ['git push --force on shared branches', 'git push --force-with-lease'], ['Giant pull requests', 'Small branches, merged daily']],
      n: 'Five common mistakes. Adding everything without looking: check status, and stage with add dash p. Committing secrets: ignore them, and scan with gitleaks. Rewriting commits others already have: only rewrite your own branch. Plain force push: use force with lease. And giant pull requests: keep branches small, and merge them often.' },
    { type: 'repos', repos: [['pcottle/learnGitBranching', 'Interactive branching game in the browser', '', 'git'], ['k88hudson/git-flight-rules', 'What to do when things go wrong', '', 'book'], ['firstcontributions/first-contributions', 'Make your first pull request', '', 'users'], ['github/gitignore', 'Ready .gitignore templates', '', 'file'], ['newren/git-filter-repo', 'Rewrite history safely', '', 'wrench'], ['gitleaks/gitleaks', 'Find secrets in commits', '', 'shield'], ['pre-commit/pre-commit', 'Shareable Git hooks', '', 'check'], ['jesseduffield/lazygit', 'A friendly terminal UI for Git', '', 'terminal']],
      n: 'Here are the practice repos. Learn git branching is an interactive game that animates every command. Git flight rules tells you what to do when things go wrong. First contributions walks you through your first pull request. Then gitignore templates, git filter repo, gitleaks, pre commit, and lazygit. Screenshot this frame.' },
    { type: 'recap', points: ['Three areas: working tree, staging area, repository', 'Commits are snapshots; branches are just pointers', 'Merge keeps history; rebase rewrites it, so only on your own branch', 'Pushed? revert. Lost? reflog. Broken? bisect', 'Small commits, small PRs, protected main, no secrets', 'Git 3.0: main, SHA-256 and reftable by default'],
      n: 'Let us recap. Every change moves between three areas: working tree, staging, and repository. Commits are snapshots, and branches are just pointers to them. Merge keeps history, and rebase rewrites it, so only rebase your own branch. If it is pushed, revert. If it is lost, reflog. If something broke, bisect. Keep commits and pull requests small, protect main, and keep secrets out. And Git three is coming, with main, S H A two five six, and reftable by default.' },
  ],
};
